28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type InsurableItemType = keyof typeof BASE_PREMIUMS;
69	
70	const basePremiumFor = (itemType: InsurableItemType): number =>
71	  BASE_PREMIUMS[itemType];
72	
73	const basePremiumForItems = (items: Item[]): number =>
74	  items.reduce(
75	    (sum, item) => sum + basePremiumFor(item.type as InsurableItemType),
76	    0,
77	  );
78	
79	const withInitialAssessmentSurcharge = (basePremium: number): number =>
80	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
81	
82	const quotePremium = (items: Item[]): number =>
83	  Math.round(
84	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
85	  );
86	
87	const runStep = (step: Step): StepResult => {
88	  if (step.op === "quote") return { premium: quotePremium(step.items) };
89	  throw new Error(`Unsupported step: ${step.op}`);
90	};
91	
92	export const runScenario = (scenario: Scenario): ScenarioResult => ({
93	  results: scenario.steps.map(runStep),
94	});
95

